    """Overlay the denser of two separated pattern bands onto the sparser one.

    Newly supplied cells are marked with 1; existing cells are preserved.
    """
    if not grid or not grid[0]:
        return []
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # Find horizontal runs of non-background rows (the task's two pattern bands).
    bands = []
    r = 0
    while r < h:
        if all(value == bg for value in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(value != bg for value in grid[r]):
            r += 1
        bands.append((start, r))
    out = [row[:] for row in grid]
    if len(bands) != 2:
        return out
    (a0, a1), (b0, b1) = bands
    if a1 - a0 != b1 - b0:
        return out

    def density(start, end):
        return sum(value != bg for row in grid[start:end] for value in row)

    # The more populated band supplies its pattern; copy only into background
    # cells in the corresponding rows of the less populated band.
    if density(a0, a1) >= density(b0, b1):
        src0, dst0 = a0, b0
    else:
        src0, dst0 = b0, a0
    height = a1 - a0
    for dr in range(height):
        for c in range(w):
            if grid[src0 + dr][c] != bg and grid[dst0 + dr][c] == bg:
                out[dst0 + dr][c] = 1
    return out

